def relative(path: Path) -> str:
    return path.relative_to(ROOT).as_posix()


def read_csv(path: Path) -> list[dict[str, str]]:
    with path.open(newline="", encoding="utf-8-sig") as handle:
        return list(csv.DictReader(handle))


def as_int(value: str | int | None) -> int:
    if value in (None, ""):
        return 0
    return int(value)


def as_float(value: str | float | None) -> float | None:
    if value in (None, ""):
        return None
    return float(value)


def percent(numerator: int, denominator: int) -> float:
    return round((100.0 * numerator / denominator), 4) if denominator else 0.0


def generated_at() -> str:
    return (
        datetime.now(timezone.utc)
        .replace(microsecond=0)
        .isoformat()
        .replace("+00:00", "Z")
    )


def base_metadata(
    *,
    timestamp: str,
    source_paths: list[Path],
    data_vintage: str,
    warnings: list[str],
) -> dict[str, Any]:
    return {
        "schema_version": "0.1.0",
        "generated_at": timestamp,
        "data_vintage": data_vintage,
        "source_files": [relative(path) for path in source_paths if path.exists()],
        "warnings": warnings,
        "limitations": GLOBAL_LIMITATIONS,
    }


def write_json(name: str, payload: dict[str, Any]) -> Path:
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    path = OUTPUT_DIR / name
    with path.open("w", encoding="utf-8") as handle:
        json.dump(payload, handle, indent=2, ensure_ascii=False)
        handle.write("\n")
    return path


def read_json(path: Path) -> dict[str, Any]:
    with path.open(encoding="utf-8") as handle:
        payload = json.load(handle)
    if not isinstance(payload, dict):
        raise ValueError(f"Expected a JSON object in {relative(path)}")
    return payload


