def broad_state_4x2500_live_state_overlay() -> dict[str, dict[str, int]]:
    """Return actual per-state 4x2500 outcomes; never include planned rows."""
    available, status = broad_state_4x2500_live_scout_status()
    if not available:
        return {}
    outcomes = read_csv(BROAD_STATE_4X2500_LIVE_DIR / "broad_state_4x2500_live_scout_results.csv")
    overlay: dict[str, dict[str, int]] = defaultdict(
        lambda: {"parseable": 0, "candidate_positive": 0, "no_candidate": 0, "failed": 0, "candidate_rows": 0}
    )
    for row in outcomes:
        state = row["state"]
        candidate_count = as_int(row.get("candidate_count"))
        if row.get("parse_status") == "parseable":
            overlay[state]["parseable"] += 1
            overlay[state]["candidate_positive" if candidate_count else "no_candidate"] += 1
        else:
            overlay[state]["failed"] += 1
        overlay[state]["candidate_rows"] += candidate_count
    if (
        sum(item["parseable"] for item in overlay.values()) != status["new_scout_covered_municipalities"]
        or sum(item["failed"] for item in overlay.values()) != status["failed_or_stopped_parses"]
        or sum(item["candidate_rows"] for item in overlay.values()) != status["candidate_count"]
    ):
        raise ValueError("4x2500 live state overlay does not reconcile to finalized scout status")
    return dict(overlay)


def build_reports_index_layer(
    *, source_index: dict[str, Any], metadata: dict[str, Any]
) -> dict[str, Any]:
    required_report_fields = {
        "id",
        "title",
        "report_type",
        "date",
        "checkpoint",
        "summary",
        "pdf_path",
        "markdown_source_path",
        "tags",
        "current",
        "created_commit",
        "metrics_snapshot",
    }
    required_metric_fields = {
        "scout_covered",
        "candidate_queue_rows",
        "candidate_positive",
        "parseable_empty",
        "failure_only",
        "tier1_eligible",
        "tier2_eligible",
    }
    reports = source_index.get("reports")
    if not isinstance(reports, list) or not reports:
        raise ValueError("Report index must contain a non-empty reports list")

    report_ids: list[str] = []
    current_count = 0
    for index, report in enumerate(reports, start=1):
        if not isinstance(report, dict):
            raise ValueError(f"Report index entry {index} must be an object")
        missing = sorted(required_report_fields - set(report))
        if missing:
            raise ValueError(f"Report index entry {index} is missing: {missing}")
        if not all(isinstance(report[field], str) and report[field].strip() for field in required_report_fields - {"tags", "current", "metrics_snapshot"}):
            raise ValueError(f"Report index entry {index} has a missing text value")
        if not isinstance(report["tags"], list) or not all(
            isinstance(tag, str) and tag.strip() for tag in report["tags"]
        ):
            raise ValueError(f"Report index entry {index} tags must be non-empty strings")
        if not isinstance(report["current"], bool):
            raise ValueError(f"Report index entry {index} current must be boolean")
        current_count += int(report["current"])
        metrics = report["metrics_snapshot"]
        if not isinstance(metrics, dict) or set(metrics) != required_metric_fields:
            raise ValueError(
                f"Report index entry {index} metrics_snapshot must contain exactly "
                f"{sorted(required_metric_fields)}"
            )
        if any(not isinstance(value, int) or value < 0 for value in metrics.values()):
            raise ValueError(f"Report index entry {index} metrics must be nonnegative integers")
        pdf_path = ROOT / "docs" / "dashboard" / report["pdf_path"]
        markdown_path = ROOT / report["markdown_source_path"]
        if not pdf_path.is_file():
            raise FileNotFoundError(f"Dashboard report PDF is missing: {relative(pdf_path)}")
        if not markdown_path.is_file():
            raise FileNotFoundError(
                f"Dashboard report Markdown source is missing: {relative(markdown_path)}"
            )
        report_ids.append(report["id"])

    if len(report_ids) != len(set(report_ids)):
        raise ValueError("Report index contains duplicate report IDs")
    if current_count != 1:
        raise ValueError("Report index must contain exactly one current report")

    historical_reports = [
        {
            **report,
            "current": False,
            "historical": True,
            "link_label": "Open historical source-discovery report PDF",
        }
        for report in reports
    ]
    repository_root_url = "https://github.com/dkyaya/gabriel-wages/blob/main/"
    verification_available, verification = broad_candidate_verification_4x3000_status()
    candidate_review_available, candidate_review = combined_broad_candidate_review_status()
    source_download_available, source_download = combined_broad_source_review_download_status()
    broad_readiness_available, broad_readiness = combined_broad_pdf_text_readiness_status()
    broad_extraction_available, broad_extraction = combined_broad_text_extraction_status()
    broad_span_available, broad_span = combined_broad_span_extraction_status()
    broad_rating_available, broad_rating = combined_broad_exact_span_rating_status()
    broad_rating_summary_available, broad_rating_summary = combined_broad_exact_span_rating_summary_status()
    broad_codification_available, broad_codification = combined_broad_rating_ingestion_codification_status()
    global_gate_available, global_gate = global_analysis_readiness_gate_status()
    broad_4x2500_prep_available, broad_4x2500_prep = broad_state_4x2500_scout_infrastructure_prep_status()
    broad_4x2500_live_available, broad_4x2500_live = broad_state_4x2500_live_scout_status()
    broad_4x2500_review_available, broad_4x2500_review = broad_state_4x2500_candidate_review_status()
    broad_4x2500_verify_available, broad_4x2500_verify = broad_state_4x2500_verification_status()
